components.css:
.lrow { display: grid; grid-template-columns: 1fr auto; gap: 1px 8px; width: 100%; text-align: left; padding: 8px 8px 9px; border: 0; border-bottom: 1px solid var(--gridline); background: none; color: inherit; font: inherit; cursor: pointer; }
.lrow-city { font-size: 13.5px; font-weight: 600; }
.lrow-when { grid-column: 1 / -1; font-size: 11px; color: var(--text-secondary); }

.detail-back { display: none; }
.table-back { margin: 0 0 8px; }
@media (max-width: 860px) {
  .detail-back { display: inline-flex; order: -1; margin: 0 0 4px; }
  .table-back { display: inline-flex; }
}
